package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import net.minecraft.core.*;import org.joml.*;
class AdcGeometryTest{
 @Test void nativeRestAngleAndProjectileAxisAgree(){var g=AdcGeometry.MODEL;for(Direction f:new Direction[]{Direction.NORTH,Direction.EAST,Direction.SOUTH,Direction.WEST})for(float yaw:new float[]{0,45,180,270})for(float pitch:new float[]{0,25,70,75}){var d=g.forward(f,yaw,pitch);assertEquals(java.lang.Math.sin(java.lang.Math.toRadians(pitch)),d.y,1e-8);assertEquals(1,d.length(),1e-8);var a=g.anchor(BlockPos.ZERO,f,"Muzzle_Anchor",yaw,pitch,0);var b=g.anchor(BlockPos.ZERO,f,"Muzzle_Anchor",yaw,pitch,.05);assertEquals(.05,a.distanceTo(b),1e-8);assertTrue(b.subtract(a).dot(d)<0);}}
 @Test void everyReservedCellMapsBackToOneRootInFourDirections(){var g=AdcGeometry.MODEL;assertEquals(245,g.cells.length);var root=new BlockPos(15,64,15);for(Direction f:new Direction[]{Direction.NORTH,Direction.EAST,Direction.SOUTH,Direction.WEST}){var set=new java.util.HashSet<BlockPos>();for(int i=0;i<g.cells.length;i++){var p=g.cell(root,f,g.cells[i]);assertTrue(set.add(p));assertEquals(root,g.root(p,f,i));}assertTrue(set.stream().anyMatch(p->p.getX()>>4!=root.getX()>>4));}}
 @Test void animatedCollisionAndAnchorsStayInsideReservedRenderEnvelope(){var g=AdcGeometry.MODEL;for(float yaw=0;yaw<360;yaw+=22.5f)for(float p=0;p<=75;p+=15){for(var b:g.boxes(BlockPos.ZERO,Direction.NORTH,yaw,p)){assertTrue(b.minX>=-3.0001&&b.maxX<=4.0001);assertTrue(b.minY>=-.0001&&b.maxY<=5.0001);assertTrue(b.minZ>=-3.0001&&b.maxZ<=4.0001);}var m=g.anchor(BlockPos.ZERO,Direction.NORTH,"Muzzle_Anchor",yaw,p,0);assertTrue(m.y>0&&m.y<5);}}
 @Test void originalGeometryAndThreeAtlasRegionsArePreserved()throws Exception{var r=java.nio.file.Path.of("src/main/resources/assets/sbwdroneconfig/adc01");var j=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(r.resolve("adc01.json"))).getAsJsonObject();assertEquals(18,j.getAsJsonArray("bones").size());assertEquals(3,j.getAsJsonArray("animations").size());assertEquals(.7,j.get("scale").getAsDouble(),1e-9);var image=javax.imageio.ImageIO.read(r.resolve("adc01.png").toFile());assertEquals(4096,image.getWidth());assertEquals(1024,image.getHeight());try(var in=new java.io.DataInputStream(java.nio.file.Files.newInputStream(r.resolve("adc01.bin")))){assertEquals(0x44454631,in.readInt());assertEquals(18,in.readInt());int faces=0;for(int i=0;i<18;i++){int n=in.readInt();faces+=n;in.skipNBytes(n*23L*4);}assertEquals(11156,faces);assertEquals(-1,in.read());}}}
